<script>
export default {
  inheritAttrs: false,
  props: {
    close: Boolean,
    scope: Element,
    // Width preset. `md` preserves the previous default (`md:max-w-2xl`).
    // Use e.g. `full`/`xl` for large, editor-like content.
    size: {
      type: String,
      default: 'md'
    }
  },
  emits: ['close'],
  computed: {
    sizeClass() {
      const sizes = {
        sm: 'md:max-w-md',
        md: 'md:max-w-2xl',
        lg: 'md:max-w-4xl',
        xl: 'md:max-w-6xl',
        full: 'md:max-w-[95vw]'
      }
      return sizes[this.size] || sizes.md
    }
  },
  mounted() {
    // Attach to the provided scope element, or fall back to the root App element
    const target = this.scope || this.$root.$el
    target.appendChild(this.$el)

    // Add ESC key listener
    this.handleKeyDown = (e) => {
      if (e.key === 'Escape' && this.close) {
        this.$emit('close')
      }
    }
    document.addEventListener('keydown', this.handleKeyDown)
  },
  beforeUnmount() {
    // Clean up when modal is destroyed
    if (this.$el.parentNode) {
      this.$el.parentNode.removeChild(this.$el)
    }
    document.removeEventListener('keydown', this.handleKeyDown)
  }
}
</script>
